// Create symbology for each geojson file
var checkersColor = {
    radius: 8,
    fillColor: "#ff0000",
    color: "#000",
    weight: 1,
    opacity: 1,
    fillOpacity: 0.8
}
var cookoutColor = {
    radius: 8,
    fillColor: "#663d17",
    color: "#000",
    weight: 1,
    opacity: 1,
    fillOpacity: 0.8
}
var inNoutColor = {
    radius: 8,
    fillColor: "#f79941",
    color: "#000",
    weight: 1,
    opacity: 1,
    fillOpacity: 0.8
}
var shakeShackColor = {
    radius: 8,
    fillColor: "#59f573",
    color: "#000",
    weight: 1,
    opacity: 1,
    fillOpacity: 0.8
}

// Add geojson files to map as layers with symbology
var checkersLayer = L.layerGroup([L.geoJSON(checkers, {
    pointToLayer: function (feature, latlng) {
    return L.circleMarker(latlng, checkersColor);
  }
})]);
var cookoutLayer = L.layerGroup([L.geoJSON(cookout, {
    pointToLayer: function (feature, latlng) {
    return L.circleMarker(latlng, cookoutColor);
  }
})]);
var inNoutLayer = L.layerGroup([L.geoJSON(inNout, {
    pointToLayer: function (feature, latlng) {
    return L.circleMarker(latlng, inNoutColor);
  }
})]);
var shakeShackLayer = L.layerGroup([L.geoJSON(shakeShack, {
    pointToLayer: function (feature, latlng) {
    return L.circleMarker(latlng, shakeShackColor);
  }
})]);

// Select basemaps for layer control
var osm = L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png', {
    maxZoom: 19,
    attribution: '© OpenStreetMap'
});

var osmHOT = L.tileLayer('https://{s}.tile.openstreetmap.fr/hot/{z}/{x}/{y}.png', {
    maxZoom: 19,
    attribution: '© OpenStreetMap contributors, Tiles style by Humanitarian OpenStreetMap Team hosted by OpenStreetMap France'
});

var USGS_USImageryTopo = L.tileLayer('https://basemap.nationalmap.gov/arcgis/rest/services/USGSImageryTopo/MapServer/tile/{z}/{y}/{x}', {
	maxZoom: 16,
	attribution: 'Tiles courtesy of the <a href="https://usgs.gov/">U.S. Geological Survey</a>'
});

// create map frame to contain features
var map = L.map('burgermap', {
    center: [39.8333, -98.5833], // Geographic center of the Contigous United States 
    zoom: 5,
    layers: [osm, checkersLayer, cookoutLayer, inNoutLayer, shakeShackLayer] // set layer visibilities when opening map.
});

// create variables for layer control
var baseMaps = {
    "OpenStreetMap": osm,
    "OpenStreetMap.HOT": osmHOT,
    "USGS Imagery Topo": USGS_USImageryTopo
};

var overlayMaps = {
    "Checkers and Rally's": checkersLayer,
    "Cookout": cookoutLayer,
    "In-N-Out": inNoutLayer,
    "Shake Shack": shakeShackLayer
};

// add layer control to map
var layerControl = L.control.layers(baseMaps, overlayMaps).addTo(map);